<script setup lang="ts">import type {Run} from '../types/domain';import Table from './common/Table.vue';import Badge from './common/Badge.vue';import {date,dec} from '../utils/format';defineProps<{runs:Run[]}>();defineEmits<{select:[run:Run]}>()</script><template><Table :headers="['主题册 / 名称','状态','预选K / 重复','平均对齐余弦','建立时间','']"><tr v-for="r in runs" :key="r.id"><td><small>VOLUME / {{String(r.id).padStart(3,'0')}}</small><strong>{{r.name}}</strong></td><td><Badge :status="r.status"/></td><td>{{r.config.k}} / {{r.config.repeats}}</td><td>{{dec(r.result.mean_alignment_similarity)}}</td><td class="mono">{{date(r.created_at)}}</td><td><button class="text-button" @click="$emit('select',r)">阅读主题册 ↗</button></td></tr></Table></template>
